```sql
/* Select buffets and coffee shops whose opening hours overlap the 07:30–16:00 window */
SELECT
    r."name",
    r."address",
    r."service_format",
    r."hours"
FROM "restaurant" AS r
WHERE (
        LOWER(r."service_format") LIKE '%buffet%'
        OR LOWER(r."service_format") LIKE '%coffee%'
      )
  /* Ensure the venue is open at some point within 07:30–16:00 */
  AND (
        /* Opening time is before 16:00 */
        (SPLIT_PART(r."hours", '-', 1))::time < '16:00'::time
        /* Closing time is after 07:30 */
        AND (SPLIT_PART(r."hours", '-', 2))::time > '07:30'::time
      )
ORDER BY r."service_format", r."name";
```

```sql
/* Список описаний блюд на вынос (takeaway) с любой датой "best before" */
/* и описаний готовых блюд (prepared) с датой "best before" = 10.11.2018 */
SELECT
    m."description",
    m."bestbefore"
FROM "meals" AS m
WHERE
    /* takeaway: любая дата bestbefore */
    LOWER(m."mealtype") = 'takeaway'
    /* prepared: дата bestbefore = 10.11.2018 (преобразуем TEXT в DATE) */
    OR (
        LOWER(m."mealtype") = 'prepared'
        AND TO_DATE(m."bestbefore", 'DD.MM.YYYY') = TO_DATE('10.11.2018', 'DD.MM.YYYY')
    );
```

```sql
/* Find communication channels shared by all customer service representatives */
SELECT c."channel_value"
FROM "channels" c
JOIN "customer_service_representatives_channels" crc ON crc."channel_id" = c."channel_id"
GROUP BY c."channel_id", c."channel_value"
HAVING COUNT(DISTINCT crc."representative_id") = (
    SELECT COUNT(DISTINCT "id") FROM "customer_service_representatives"
);
```

